{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not specify the use of Instance Metadata Service Version 2 (IMDSv2). IMDSv1 is less secure as it does not require session tokens, making it vulnerable to certain types of attacks."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The launch template does not enforce the use of HTTP tokens for accessing the instance metadata service. This can allow unauthorized access to sensitive metadata."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The launch template does not enforce the use of HTTP tokens for accessing the instance metadata service. This can allow unauthorized access to sensitive metadata."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Sensitive information exposed in user_data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The user_data script includes sensitive information such as database passwords and API keys in plaintext. This can lead to credential exposure if the instance metadata or logs are accessed by unauthorized users."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"web_app\" {\n  name_prefix   = \"automated-employee-onboarding-platform-lt-web-\"\n  image_id      = data.aws_ami.ubuntu.id\n  instance_type = var.instance_type\n  key_name      = var.key_pair_name\n  vpc_security_group_ids = [aws_security_group.web_app.id]\n  metadata_options {\n    http_tokens = \"required\"\n    http_endpoint = \"enabled\"\n  }\n  user_data = base64encode(<<-EOF\n              # Sensitive information removed from user_data\n              apt-get update\n              apt-get install -y nginx nodejs npm\n              systemctl start nginx\n              systemctl enable nginx\n              EOF\n  )\n  tag_specifications {\n    resource_type = \"instance\"\n  }\n}",
  "fix_summary": "Enabled IMDSv2 by setting 'http_tokens' to 'required' and 'http_endpoint' to 'enabled' in the metadata_options block. Removed sensitive information (database password and API key) from the user_data script to prevent credential exposure."
}
